        id: 'cc-sd-02',
        title: '中性化深さの推定計算と将来予測',
        emoji: '📐',
        body: `▼ゼロから：診断士の試験で必ず問われるのが「この構造物、あと何年でかぶりの位置まで中性化するのか」という計算です。使う道具はたった一本の式、x＝A√t だけ。ここで重要なのは、A（中性化速度係数）は現地で測った中性化深さから逆算するという実務の流れです。設計図から予測するのではなく、実際にドリルで穴をあけたりコアを抜いたりして、フェノールフタレイン溶液を噴霧して測った深さを出発点にします。測った深さと、その構造物が建ってからの年数がわかれば、Aは A＝x÷√t で求まります。あとはこのAを使って将来を延長するだけです。計算そのものは中学生でもできますが、平方根の扱いと単位、そして「かぶりに達する年がそのまま寿命ではない」という考え方でつまずく人が非常に多い分野です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 基本三式
━━━━━━━━━━━━━━━━━━━━━━
・深さを求める：x ＝ A × √t
・速度係数を求める：A ＝ x ÷ √t
・到達年数を求める：t ＝ (x ÷ A) の2乗★
この3つ目が「あと何年」を答える式。順番を逆にすると答えが桁で狂います。

【図解】例題1　中性化速度係数を実測から求める
　項目｜記号｜値
　経過年数｜t｜16年
　実測中性化深さ｜x｜12ミリメートル
　求める係数｜A｜未知
　⚠ ルート16は4。ここで16をそのまま割らないこと。
　式：A＝x÷√t
　代入：A＝12÷√16＝12÷4
　答え：A＝3.0 ミリメートル毎ルート年★

【図解】例題2　将来の中性化深さを予測する
　項目｜記号｜値
　中性化速度係数｜A｜3.0
　予測時点｜t｜49年
　求める深さ｜x｜未知
　⚠ ルート49は7。年数が約3倍になっても深さは約1.75倍にしかならない。
　式：x＝A×√t
　代入：x＝3.0×√49＝3.0×7
　答え：x＝21 ミリメートル

【図解】例題3　かぶり位置に達する年数（最重要）
　項目｜記号｜値
　中性化速度係数｜A｜3.0
　設計かぶり｜c｜30ミリメートル
　求める年数｜t｜未知
　⚠ 割ってから2乗する。2乗してから割ると誤答になる典型ミス。
　式：t＝(c÷A)の2乗
　代入：t＝(30÷3.0)の2乗＝10の2乗
　答え：t＝100年★

━━━━━━━━━━━━━━━━━━━━━━
🔑 かぶり不足があるときの実務的判断
━━━━━━━━━━━━━━━━━━━━━━
同じA＝3.0でも、施工誤差でかぶりが20ミリメートルしかない部位では
　t＝(20÷3.0)の2乗＝6.67の2乗＝約44年
となり、100年が44年に縮みます。かぶりが3分の2になると寿命は約9分の4、つまり半分以下★。中性化に対しては「かぶりの2乗で効く」ことを体で覚えてください。逆にかぶりを1.5倍にすれば寿命は2.25倍になります。設計図どおりのかぶりがあるかどうかを電磁誘導法で確認することが、診断の第一歩になる理由がここにあります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 中性化残りという考え方
━━━━━━━━━━━━━━━━━━━━━━
実務では「中性化がかぶり表面まで来たら即アウト」ではなく、安全側に余裕を見ます。かぶりから中性化深さを引いた値を中性化残りと呼び、これが10から25ミリメートル程度を下回らないよう管理します。塩化物イオンの影響がある環境ではこの残りを大きく（25ミリメートル程度）、乾燥した屋内では小さく（10ミリメートル程度）設定します。したがって寿命計算は
　t＝((かぶり－中性化残り)÷A)の2乗
とするのが本来の姿です。かぶり30、中性化残り10、A＝3.0なら
　t＝(20÷3.0)の2乗＝約44年
となります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 中性化速度係数の目安を持っておく
━━━━━━━━━━━━━━━━━━━━━━
計算問題では係数が与えられますが、記述や判断の問題では「その値が妥当かどうか」を問われます。おおまかな相場観として、屋外の普通ポルトランドセメントで水セメント比0.55程度なら、中性化速度係数はおおむね2から4ミリメートル毎ルート年。屋内や水セメント比の大きい古い構造物では5から8に達することもあります。逆に水セメント比0.4以下の高強度コンクリートでは1以下になることも珍しくありません。したがって、たとえば築30年で中性化深さが30ミリメートルなら
　A＝30÷√30＝30÷5.48＝約5.5
となり、「屋内か、水セメント比が大きいか、養生が不十分だったか」を疑う手がかりになります。数字を出したら必ず相場と比べる、というのが診断士の作法です。加えて、同じ構造物でも南面と北面、屋外と屋内、仕上げの有無で係数は大きく異なるため、部位ごとに代表点を選び、最も厳しい値で寿命を評価します。

■ 頻出ひっかけ・本試験での問われ方
×「経過年数が2倍になれば中性化深さも2倍」→ ルート2倍すなわち約1.41倍。
×「A＝x÷t」→ 分母はルートt。
×「t＝c÷A」→ 2乗を忘れている最頻出の誤答。
○「促進中性化試験（二酸化炭素濃度5パーセント、温度20度、湿度60パーセント）の結果は、実環境の濃度比を考慮した係数で換算する」→ 正しい。促進試験のおよそ1週間が実環境の約1年に相当するという換算がよく使われる。
○「同一構造物でも部位によりAは異なるため、代表点を複数とる」→ 正しい。

★ここだけ暗記
A＝x÷√t、x＝A√t、t＝(x÷A)の2乗。かぶりは2乗で効く。実務の寿命は「かぶり－中性化残り」を使う。`,
