        body: `▼ゼロから：乾燥収縮は「水が外へ逃げるから縮む」現象でした。ところが、外へ水が一滴も逃げなくても、コンクリートは縮みます。セメントと水が反応して水和物になるとき、できた水和物の体積は元のセメントと水の合計体積より小さいのです。この体積の目減りが自己収縮の正体です。かつては無視できる程度とされていましたが、高強度コンクリートや高流動コンクリートのように水セメント比が極端に小さい配合が普及すると、自己収縮が乾燥収縮に匹敵する大きさになり、材齢1日から数日という早い時期にひび割れを生じるようになりました。近年の重要テーマであり、試験でもよく問われます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 自己収縮とは何か
━━━━━━━━━━━━━━━━━━━━━━
・定義：セメントの水和反応により、外部との水分の出入りがない状態で生じる体積減少★
・原因の中心は自己乾燥。水和が進むと未反応の水が消費され、内部の毛細管が空になっていく。空になった細孔に働く毛管張力が組織を引き寄せて縮ませる
・水セメント比が小さいほど大きい★（自由水が少なく、すぐに自己乾燥に至るため）
・進行が速い。凝結が終わったころから始まり、材齢1日から7日程度で大部分が進む★
・水セメント比0.5程度では100マイクロメートル毎メートル以下と小さいが、0.3では300から500マイクロメートル毎メートルに達する

━━━━━━━━━━━━━━━━━━━━━━
🔑 乾燥収縮との違い
━━━━━━━━━━━━━━━━━━━━━━
・水分の出入り：自己収縮はなし、乾燥収縮は外部への逸散が原因
・発生時期：自己収縮は極めて早い（材齢数日）、乾燥収縮は長期
・部材寸法の影響：自己収縮は部材寸法にほとんど依存しない（内部で完結するため）、乾燥収縮は薄い部材ほど速い★
・水セメント比の影響：自己収縮は小さいほど大きい、乾燥収縮は大きいほど大きい★（逆向き）
この「水セメント比に対する向きが逆」という点が最頻出のポイントです。低水セメント比にすれば乾燥収縮は減るが自己収縮は増える、というトレードオフがあります。

【図解】自己収縮と乾燥収縮の比較
　項目｜自己収縮｜乾燥収縮
　水分の逸散｜なし★｜あり
　水セメント比が小さいと｜大きくなる★｜小さくなる
　主な発生時期｜材齢1日から7日｜数か月から数年
　⚠ 高強度コンクリートでは自己収縮が支配的。低水セメント比だから安心、は誤り。

━━━━━━━━━━━━━━━━━━━━━━
🔑 大きくする要因と抑える方法
━━━━━━━━━━━━━━━━━━━━━━
・水セメント比が小さいほど大きい
・シリカフュームや高炉スラグ微粉末を多く用いると大きくなる★（微細な組織ほど毛管張力が高い）
・粉末度の高いセメントほど大きい
・温度が高いほど水和が速く、初期の収縮が大きい
抑える方法としては、膨張材の使用（収縮を打ち消す）、収縮低減剤の使用、そして最も効果的とされるのが内部養生です。あらかじめ水を吸わせた人工軽量骨材や高吸水性ポリマーを混入しておき、自己乾燥が始まったときに内部から水を供給して毛管張力の発生を抑えます★。もちろん外部からの湿潤養生（散水、湛水、シート）も、表層部については有効です。

━━━━━━━━━━━━━━━━━━━━━━
🔑 マスコンクリートとの関係
━━━━━━━━━━━━━━━━━━━━━━
温度ひび割れの解析では、以前は水和熱による温度変化だけを考えていましたが、高強度のマスコンクリートでは温度降下による収縮に自己収縮が重なるため、両者を合わせて評価しないと危険側の判断になります★。実務の温度応力解析では、自己収縮ひずみを温度ひずみに加算して応力を求めます。低熱ポルトランドセメントは水和熱が小さいだけでなく自己収縮も小さいため、この点でも高強度マスコンクリートに適しています。

━━━━━━━━━━━━━━━━━━━━━━
🔑 自己収縮ひび割れの見つけ方
━━━━━━━━━━━━━━━━━━━━━━
自己収縮によるひび割れは、材齢が極めて若い時期に現れるため、脱型した直後にすでに存在していることが多いのが特徴です。高強度コンクリートを用いた柱や梁、プレキャスト部材、鋼管充填コンクリート、グラウトなどで報告されています。外観は乾燥収縮ひび割れとよく似ており、単独で見分けるのは困難です。したがって判定には、配合（水セメント比や結合材の種類）、部材寸法、脱型時期、養生方法といった施工記録が不可欠になります。水セメント比0.3前後のコンクリートで、脱型直後にすでに部材を横断するひび割れがあれば、自己収縮と温度応力の複合を疑うのが定石です★。なお、自己収縮そのものは有害な化学反応ではないため、ひび割れが安定していれば注入補修で処理し、その後の進行はほとんど問題になりません。

■ 頻出ひっかけ・本試験での問われ方
×「自己収縮は水セメント比が大きいほど大きい」→ 小さいほど大きい★。乾燥収縮と逆。
×「自己収縮は外部への水分逸散によって生じる」→ 逸散がなくても生じる。
×「自己収縮は部材が薄いほど大きい」→ 部材寸法にほとんど依存しない。
×「自己収縮は長期にわたって緩やかに進行する」→ 初期に急速に進む。
○「膨張材や内部養生は自己収縮の低減に有効である」→ 正しい。

★ここだけ暗記
自己収縮は水分の出入りなしで生じる初期の収縮。水セメント比が小さいほど大きく、乾燥収縮と逆向き。材齢数日で大部分が進む。対策は膨張材、収縮低減剤、内部養生。`,
