        emoji: '🏗️',
        body: `▼ゼロから：これまで見てきたひび割れは、材料や施工や環境が原因でした。ここで扱う構造ひび割れは、荷重そのものが原因で生じるひび割れです。つまり「この部材には、想定を超える力がかかっている」という危険信号であり、耐久性の問題ではなく安全性の問題です。診断において最も緊急度が高いのがこのタイプで、見つけたら原因が解消されない限り放置してはいけません。幸い、構造ひび割れは発生する場所と方向に明確な法則があります。力の流れを思い浮かべれば、どこにどんな向きで割れるかは予測できます。逆に言えば、位置と方向を見れば何の力が効いているかが読み取れるのです。

━━━━━━━━━━━━━━━━━━━━━━
🔑 曲げひび割れ
━━━━━━━━━━━━━━━━━━━━━━
・発生位置：曲げモーメントが最大となる断面の引張側★
　　単純ばり：支間中央の下面
　　片持ばり：固定端の上面★
　　連続ばり：支間中央下面と中間支点上面の両方
・方向：部材軸に直角（鉛直方向）に、引張縁から中立軸に向かって伸びる★
・特徴：荷重が増えると本数が増え、幅が大きくなる。荷重を取り除くと幅が小さくなる（可逆性がある）
・意味：鉄筋コンクリートでは、設計上ひび割れの発生を許容している。使用限界状態としての幅の制限を満たしていれば問題ない
・危険な兆候：幅が急に大きくなる、本数が増え続ける、たわみが増大する

━━━━━━━━━━━━━━━━━━━━━━
🔑 せん断ひび割れ
━━━━━━━━━━━━━━━━━━━━━━
・発生位置：せん断力の大きい支点近傍★
・方向：部材軸に対しておよそ45度の斜め方向。支点に向かって斜め下へ、または中立軸付近から斜めに伸びる★
・特徴：発生してから破壊までの余裕が小さく、ぜい性的に進行する。曲げひび割れよりはるかに危険★
・見分け：腹部（ウェブ）の中立軸付近から斜めに発生する斜め引張ひび割れと、曲げひび割れが斜めに屈曲して伸びる曲げせん断ひび割れがある
・対応：ただちに荷重制限や通行規制を検討し、せん断補強（鋼板接着、連続繊維シート、外ケーブル、増厚）を計画する

【図解】構造ひび割れの位置と方向
　種類｜位置｜方向
　曲げひび割れ｜単純ばり支間中央の下面★｜部材軸に直角
　曲げひび割れ｜片持ばり固定端の上面★｜部材軸に直角
　せん断ひび割れ｜支点近傍の腹部｜部材軸に対し約45度★
　⚠ 片持ばりで下面に横断ひび割れがあれば、曲げではなく別の原因（型枠の変形、支保工の早期取外し）を疑う。

━━━━━━━━━━━━━━━━━━━━━━
🔑 その他の荷重起因のひび割れ
━━━━━━━━━━━━━━━━━━━━━━
・付着割裂ひび割れ：鉄筋に沿ってかぶりが割れる。鉄筋の定着部や重ね継手部で、付着応力が大きい場合に生じる。腐食ひび割れと外見が似るため注意★
・支圧によるひび割れ：支承部やPC定着部など、局部的に大きな圧縮力が作用する位置に、力の方向に平行に生じる（横引張が原因）
・ねじりひび割れ：部材の周囲をらせん状に取り巻く斜めひび割れ
・不同沈下によるひび割れ：建物の一部が沈下すると、沈下側に向かって斜めのひび割れが開口部などから伸びる。壁面全体を斜めに横切るのが特徴★
・圧縮によるひび割れ：圧縮応力の方向に平行な縦のひび割れ。終局に近い危険な状態

━━━━━━━━━━━━━━━━━━━━━━
🔑 構造ひび割れを疑ったときの進め方
━━━━━━━━━━━━━━━━━━━━━━
まず、設計図書と実際の配筋を照合します。電磁誘導法やレーダ法で鉄筋径、本数、間隔、かぶりを確認し、設計と違いがないかを調べます。次に、供用条件が設計時から変わっていないか（交通量の増加、車両重量の増大、用途変更による積載荷重の増加）を確認します。そのうえで、載荷試験によるたわみやひずみの測定、あるいは構造解析による照査を行い、現状の耐力を評価します。進行性の確認も欠かせず、ひび割れ幅の継続計測やAE法による内部の破壊音の監視を行うことがあります★。

━━━━━━━━━━━━━━━━━━━━━━
🔑 構造ひび割れと非構造ひび割れの決定的な違い
━━━━━━━━━━━━━━━━━━━━━━
両者を分ける最大の手がかりは、荷重に対する応答があるかどうかです。構造ひび割れは、大型車が通過したときや積載が増えたときに幅が広がり、荷重が去ると戻ります。この開閉挙動をひび割れ変位計で測れば、構造起因であることをほぼ確定できます★。一方、乾燥収縮や温度によるひび割れは、荷重ではなく気温や湿度の変化に応じて開閉します。したがって計測は、荷重の記録や気温の記録と同時に行い、どちらと相関するかを見るのが実務です。もうひとつの手がかりは位置の一致で、曲げモーメント図やせん断力図の大きい位置とひび割れの分布が一致していれば構造起因の可能性が高いと言えます。構造ひび割れは注入で塞いでも力の流れは変わらないため、補修ではなく補強、あるいは荷重の低減という対応が必要になる点も押さえてください。

■ 頻出ひっかけ・本試験での問われ方
×「せん断ひび割れは部材軸に直角に生じる」→ 約45度の斜め。直角は曲げ★。
×「片持ばりの曲げひび割れは自由端の下面に生じる」→ 固定端の上面。
×「曲げひび割れが生じた鉄筋コンクリート部材は直ちに危険である」→ 設計上許容されている。幅と進行性で判断する。
×「せん断ひび割れは曲げひび割れより安全側の現象である」→ 逆。ぜい性的で危険★。
○「鉄筋に沿ったひび割れは腐食のほか付着割裂の可能性もある」→ 正しい。

★ここだけ暗記
曲げは引張縁に直角、せん断は支点付近に45度。片持ばりは固定端上面。せん断はぜい性で最も危険。不同沈下は壁を斜めに横切る。`,
