・付随現象：赤褐色の錆汁が線状ににじむ。進むとかぶりが浮き、打音で濁った音、最終的に剥落して鉄筋が露出
・部位の偏り：かぶりが薄い部位、隅角部、施工継目、水がかりのある部位に先行して現れる
・中性化型と塩害型の違い：中性化型は建物全体に広く均等に、塩害型は飛沫帯や凍結防止剤の影響範囲に帯状に集中する傾向がある★
・確認方法：中性化深さ試験と塩化物イオン量分析、自然電位法を組み合わせる

