        id: 'cc-sd-27',
        title: '超音波法と衝撃弾性波法',
        emoji: '📡',
        body: `▼ゼロから：コンクリートの中に音を通して、その伝わり方から内部を推し量る。これが弾性波を使った非破壊試験の考え方です。音は密で健全な材料の中を速く伝わり、空隙やひび割れがあると遠回りするので遅くなります。あるいは、境界にぶつかると跳ね返ってきます。この「速さ」を使うのが超音波法、「跳ね返り（反射）」や「共振」を使うのが衝撃弾性波法です。どちらも弾性波を使う点は同じですが、超音波法は数十キロヘルツから数百キロヘルツの連続的な超音波を専用の発振子で送るのに対し、衝撃弾性波法はハンマーや小球で叩いて発生させた低い周波数の波を使う、という違いがあります。

━━━━━━━━━━━━━━━━━━━━━━
🔑 超音波法（超音波パルス伝播速度法）
━━━━━━━━━━━━━━━━━━━━━━
・発振子と受振子を対向させ、パルスが通過するのに要した時間を測る
・伝播速度＝距離÷時間★
・健全なコンクリートの縦波速度はおおむね 3500から4500 メートル毎秒★
・3000メートル毎秒を下回れば劣化や欠陥を疑う
・測定方法は3種類
　　対向法（透過法）：両面から挟む。最も精度が高い★
　　斜角法：隣り合う面から斜めに測る
　　表面法（同一面法）：同じ面に間隔を変えて置き、時間差から表層の速度を求める。劣化層の厚さ推定に使える★
・接触面には必ずグリースなどの接触媒質を塗る。空気が挟まると波が伝わらない
・分かること：ひび割れ深さ、内部欠陥の有無、劣化層の厚さ、弾性係数、強度の推定（精度は低い）

【図解】例題　超音波伝播速度を求める
　項目｜記号｜値
　部材厚さ（伝播距離）｜L｜400 ミリメートル
　伝播時間｜T｜105 マイクロ秒
　求める速度｜V｜未知
　⚠ 単位をそろえる。ミリメートルとマイクロ秒なら、答えはそのままキロメートル毎秒になる。
　式：V＝L÷T
　代入：V＝400÷105＝3.81
　答え：V＝約3.8 キロメートル毎秒 すなわち 3810 メートル毎秒 → 健全な範囲★

━━━━━━━━━━━━━━━━━━━━━━
🔑 衝撃弾性波法
━━━━━━━━━━━━━━━━━━━━━━
・小さな鋼球やハンマーで打撃して弾性波を発生させ、内部で反射して戻る波を受振する
・代表的な手法が衝撃弾性波法（インパクトエコー法）で、板厚方向の多重反射による共振周波数から厚さや欠陥深さを求める★
　　深さ＝縦波速度÷(2×共振周波数)
・分かること：部材厚さ、内部の空隙やはく離の深さ、ひび割れ深さ、PCグラウトの充填不足★
・片面からの測定が可能なので、床版上面やトンネル覆工のように片側からしか触れない部材に有効★
・打撃点と受振点の距離、鋼球の径（発生する周波数を左右する）の選定が結果を左右する

【図解】超音波法と衝撃弾性波法の比較
　項目｜超音波法｜衝撃弾性波法
　波の発生｜発振子による超音波★｜打撃による弾性波★
　周波数｜数十から数百キロヘルツ｜数キロから数十キロヘルツ
　主な用途｜伝播速度から品質と欠陥を推定｜反射と共振から厚さや深さを特定
　⚠ 周波数が高いほど分解能は上がるが減衰も大きく、深部には届かない。

━━━━━━━━━━━━━━━━━━━━━━
🔑 精度を左右する要因
━━━━━━━━━━━━━━━━━━━━━━
・含水状態：湿っているほど速度は速くなる★（水中を音が速く伝わるため）
・鉄筋の存在：鋼中の音速はコンクリートより速いため、鉄筋に沿って伝播すると見かけの速度が大きく出る。測線は鉄筋を避ける★
・骨材の種類と量：骨材が多いほど速い
・温度、ひび割れ、空隙の状態
・測定面の粗さと接触状態

━━━━━━━━━━━━━━━━━━━━━━
🔑 ひび割れ深さの推定
━━━━━━━━━━━━━━━━━━━━━━
表面法を応用し、ひび割れをまたいで発振子と受振子を置くと、波はひび割れの先端を回り込んで伝わるため、伝播時間が長くなります。ひび割れがない場合との時間差から、幾何学的にひび割れ深さを算出できます（Tc-To法、BS法などが代表的）。ただし、ひび割れの内部に水や土砂、遊離石灰が詰まっていると波が直進してしまい、深さを過小評価します★。また、鉄筋がひび割れを横切っていると同様に過小評価になります。

■ 頻出ひっかけ・本試験での問われ方
×「超音波伝播速度は乾燥しているほど速い」→ 湿潤なほど速い★。
×「超音波法は片面からしか測れない」→ 対向法が基本。片面が得意なのは衝撃弾性波法★。
×「健全なコンクリートの伝播速度は約1500メートル毎秒である」→ 3500から4500。1500は水中の音速。
×「ひび割れ内に水があっても深さの推定精度は変わらない」→ 過小評価する。
○「衝撃弾性波法はPCグラウトの充填不足の検出に用いられる」→ 正しい。

★ここだけ暗記
超音波は速度、衝撃弾性波は反射と共振。健全は3500から4500メートル毎秒。湿潤で速く、鉄筋沿いで速く出る。片面からなら衝撃弾性波法。`,
