・コア法：採取したコアを割裂し、新しい破断面に噴霧して、表面から変色境界までの距離を測る。最も確実★
・ドリル法（削孔粉法）：ドリルで孔を開け、排出される粉にフェノールフタレイン溶液をかけ、呈色し始めた深さを読む。簡便だが精度は劣る
