        title: '性能低下曲線と余寿命予測',
        emoji: '📊',
        body: `▼ゼロから：構造物の性能は、時間とともにどう落ちていくのか。横軸に時間、縦軸に性能をとって描いた線が性能低下曲線です。新設時は要求性能を大きく上回っていますが、劣化が進むにつれて下がり、いつか要求性能の限界を下回る。その交点までの年数が寿命です。そして現在から寿命までの残り年数が余寿命です。この考え方が維持管理計画のすべての基礎になります。補修を行えば曲線は一段持ち上がり、寿命が延びる。予防的に何度も小さな補修を行うほうが、限界まで放置して大規模に直すより総費用が安くなる。この絵が頭に入っていれば、維持管理の設問はほぼ解けます。

━━━━━━━━━━━━━━━━━━━━━━
🔑 性能低下曲線の読み方
━━━━━━━━━━━━━━━━━━━━━━
・縦軸の性能は、安全性能、使用性能、耐久性能のいずれかを指標化したもの
・横軸は時間（材齢、供用年数）
・要求性能の水準（管理限界）を水平な線として引く
・性能低下曲線が管理限界と交わる時点が寿命★
・曲線の形は劣化機構により異なる。中性化や塩害では潜伏期はほぼ水平で、腐食が始まると下がり始め、ひび割れ後は急降下する（下に凸の形）★
・補修を行うと性能が回復して曲線が上へジャンプし、その後は新たな傾きで低下していく

━━━━━━━━━━━━━━━━━━━━━━
🔑 余寿命予測の考え方
━━━━━━━━━━━━━━━━━━━━━━
余寿命は次の手順で求めます。
1　現在の劣化の程度を実測する（中性化深さ、塩化物イオン量、断面減少率など）
2　その実測値から劣化速度（中性化速度係数、拡散係数、腐食速度）を逆算する
3　限界とする状態を定義する（かぶりへの到達、腐食発生限界、許容断面減少率など）
4　限界に達する時期を計算する
5　現在の材齢を引いて余寿命とする★

【図解】例題1　中性化による余寿命
　項目｜記号｜値
　現在の材齢｜t1｜25年
　実測中性化深さ｜x1｜15 ミリメートル
　かぶり｜c｜36 ミリメートル
　⚠ ルート25は5。中性化残りを0とした場合の余寿命を求める。
　式1：A＝x1÷√t1
　代入：A＝15÷5＝3.0 ミリメートル毎ルート年
　式2：t＝(c÷A)の2乗
　代入：t＝(36÷3.0)の2乗＝12の2乗＝144年
　答え：余寿命＝144－25＝119年★

【図解】例題2　中性化残りを10ミリメートルとした場合
　項目｜記号｜値
　中性化速度係数｜A｜3.0 ミリメートル毎ルート年
　かぶり｜c｜36 ミリメートル
　管理する中性化残り｜r｜10 ミリメートル
　⚠ 到達させてよい深さは c－r。ここを間違えると答えが大きくずれる。
　式：t＝((c－r)÷A)の2乗
　代入：t＝((36－10)÷3.0)の2乗＝(26÷3.0)の2乗＝8.67の2乗＝75.2
　答え：寿命は約75年、余寿命は 75－25＝50年★

【図解】例題3　鋼材の断面減少からの余寿命
　項目｜記号｜値
　腐食速度｜v｜0.05 ミリメートル毎年（半径方向）
　現在の断面減少量｜d1｜0.4 ミリメートル
　許容する断面減少量｜dlim｜1.0 ミリメートル
　⚠ 残り量を速度で割る。現在値をそのまま割らないこと。
　式：余寿命＝(dlim－d1)÷v
　代入：(1.0－0.4)÷0.05＝0.6÷0.05
　答え：余寿命＝12年★

━━━━━━━━━━━━━━━━━━━━━━
🔑 予測の不確実性への対応
━━━━━━━━━━━━━━━━━━━━━━
劣化予測には大きな不確実性があります。環境条件の変動、材料のばらつき、かぶりのばらつき、測定誤差。したがって実務では次の工夫をします。安全側の値（最も厳しい測定点、最小かぶり）を採用する。予測に安全係数を乗じる。定期点検の結果で予測を更新していく（逐次更新）★。この「観測しながら予測を修正する」考え方が、現代の維持管理の基本姿勢です。1回の予測で寿命を決めつけるのではなく、点検のたびに実測値で補正していきます。

■ 頻出ひっかけ・本試験での問われ方
×「余寿命は寿命そのものである」→ 寿命から現在の材齢を引いた残りの年数★。
×「性能低下曲線は直線的に低下する」→ 劣化機構により形が異なり、多くは加速的に低下する。
×「一度予測した余寿命は見直す必要がない」→ 点検結果で逐次更新する。
×「中性化残りを考慮すると余寿命は長くなる」→ 短くなる★。余裕を見る分だけ限界が手前に来る。
○「補修を行うと性能低下曲線が上方に回復する」→ 正しい。

★ここだけ暗記
寿命は性能低下曲線が管理限界と交わる時点、余寿命はそこから現在の材齢を引いた年数。中性化ならA＝x÷√t、t＝((c－r)÷A)の2乗。腐食なら残り量÷速度。予測は点検で逐次更新する。`,
